// ════════════════════════════════════════════════════════════════
// Glossaire statique FR → PT (mode « Português »).
//
// Même rôle que UI_GLOSSARY (glossary.js) pour l'anglais, UI_GLOSSARY_ES
// (glossaryEs.js) pour l'espagnol, UI_GLOSSARY_DE (glossaryDe.js) pour
// l'allemand et UI_GLOSSARY_IT (glossaryIt.js) pour l'italien : le
// vocabulaire d'interface le plus fréquent bascule instantanément, hors ligne
// et sans appel IA. Le reste (recettes, étapes, notes…) part à l'IA puis au
// cache.
//
// MÊMES CLÉS que UI_GLOSSARY, dans le même ordre : toute entrée ajoutée au
// glossaire anglais doit l'être ici aussi. `npm run lint:glossary` le vérifie.
//
// Registre : portugais européen (pt-PT), orthographe de l'accord de 1990,
// ton d'interface concis, jamais de tutoiement. Boutons et actions à
// l'infinitif, comme les logiciels portugais (« Guardar », « Eliminar »,
// « Cancelar », « Editar », « Imprimir »), phrases adressées à la personne à
// la troisième personne de politesse (« Escolha », « Tente novamente »),
// guillemets « » sans espace. Vocabulaire du Portugal : ecrã, ficheiro,
// utilizador, equipa, definições, telemóvel, registo, partilhar.
// Vocabulaire métier aligné sur la tâche `translate` d'ai-proxy : carte →
// ementa (carte des boissons → carta de bebidas, carte des vins → carta de
// vinhos), carte bancaire → cartão bancário, fiche technique → ficha técnica,
// fiche salle → ficha de sala, perte → perda, pointage → registo de ponto
// (pointer → registar o ponto), planning → escala, relevé → registo,
// inventaire → inventário, établissement → estabelecimento, commande →
// pedido (bon de commande → nota de encomenda), ticket de caisse → conta,
// bon de cuisine → talão, envoyer la suite → mandar seguir, chiffrage →
// custeio, dressage → empratamento, réservation → reserva, couverts →
// cobertos, étages → andares, femme de chambre → empregada de andares,
// nuitée → dormida, taxe de séjour → taxa turística, TVA → IVA, fiduciaire →
// fiduciária. Mise en place, chef de partie, commis et CCNT restent tels
// quels.
// ════════════════════════════════════════════════════════════════

