  "Ces chiffres sont réservés à la direction et aux personnes qui règlent les factures. Demandez à votre consultant le droit « Régler les factures ».": "Estes números estão reservados à direção e às pessoas que pagam as faturas. Peça ao seu consultor o direito «Pagar as faturas».",
  "La comptabilité n'est pas encore activée sur la base de données.": "A contabilidade ainda não está ativada na base de dados.",
  "Les achats et les marges se lisent déjà ; la saisie du chiffre d'affaires, les charges fixes, les salaires et la banque arriveront avec elle.": "As compras e as margens já se leem; a introdução do volume de negócios, os custos fixos, os salários e o banco chegarão com ela.",
  "La comptabilité de l'app prépare vos chiffres et vos pièces pour la fiduciaire. Elle ne tient pas les comptes et n'établit ni le décompte TVA officiel ni les salaires.": "A contabilidade da app prepara os seus números e documentos para a fiduciária. Não faz a contabilidade nem emite a declaração oficial de IVA nem os salários.",
  "Aucun inventaire validé : la période d'inventaire commence au premier inventaire validé.": "Nenhum inventário validado: o período de inventário começa no primeiro inventário validado.",
  "Montants TVA comprise, comme sur le ticket de caisse du soir.": "Montantes com IVA incluído, como no talão de caixa da noite.",
  "La caisse a enregistré": "A caixa registou",
  "ce jour-là. Une saisie ici la remplace pour ce jour.": "nesse dia. Uma introdução aqui substitui-o para esse dia.",
  "Seule une personne qui règle les factures peut saisir le chiffre d'affaires.": "Só uma pessoa que paga as faturas pode introduzir o volume de negócios.",
  "Une charge fixe se saisit une fois : l'app la répartit sur chaque mois. N'importez pas aussi sa facture dans Factures & achats, sinon elle compte deux fois.": "Um custo fixo introduz-se uma vez: a app reparte-o por cada mês. Não importe também a sua fatura em Faturas e compras, senão conta duas vezes.",
  "Supprimer cette charge ?": "Eliminar este custo?",
  "Elle disparaît aussi des mois passés ; pour l'arrêter seulement, indiquez une date de fin.": "Desaparece também dos meses passados; para o parar apenas, indique uma data de fim.",
