  "Dossier de caisse téléchargé.": "Dossiê de caixa transferido.",
  "Terminal de paiement": "Terminal de pagamento",
  "Au tap sur « Carte », la caisse envoie le montant au terminal ; le client paie sur le terminal ; la caisse reçoit « accepté » ou « refusé » et pose le paiement toute seule.": "Ao tocar em «Cartão», a caixa envia o montante para o terminal; o cliente paga no terminal; a caixa recebe «aceite» ou «recusado» e regista o pagamento sozinha.",
  "La caisse ne voit jamais une carte : ni numéro, ni date, ni code. Elle garde seulement le résultat (marque, quatre derniers chiffres, code d'autorisation). L'argent va du prestataire à la maison, sans passer par l'app.": "A caixa nunca vê um cartão: nem número, nem data, nem código. Guarda apenas o resultado (marca, quatro últimos algarismos, código de autorização). O dinheiro vai do prestador para a casa, sem passar pela app.",
  "Terminaux reliés": "Terminais ligados",
  "Les terminaux n'ont pas pu être lus. Fermez les Réglages et rouvrez-les.": "Não foi possível ler os terminais. Feche as Definições e volte a abri-las.",
  "Aucun terminal relié : les cartes s'encaissent à la main, comme aujourd'hui.": "Nenhum terminal ligado: os cartões cobram-se à mão, como hoje.",
