  "Jumelage": "Emparelhamento",
  "Aucun prestataire réel n'est encore proposé. Le terminal simulé sert à s'entraîner en mode test ; un vrai terminal sera ajouté quand son prestataire aura confirmé ses règles et fourni un moyen d'essai sans argent réel.": "Ainda não é proposto nenhum prestador real. O terminal simulado serve para treinar em modo de teste; um terminal real será adicionado quando o seu prestador tiver confirmado as suas regras e fornecido um meio de teste sem dinheiro real.",
  "Nom du terminal, tel que l'équipe le verra": "Nome do terminal, tal como a equipa o verá",
