  "Numéro de série, lu sous le terminal": "Número de série, lido por baixo do terminal",
  "Saisie masquée": "Introdução oculta",
  "La clé part une seule fois vers le serveur, qui la range dans son coffre. Elle ne revient jamais à l'écran : seuls ses quatre derniers caractères seront rappelés.": "A chave segue uma única vez para o servidor, que a guarda no seu cofre. Nunca volta ao ecrã: só os seus quatro últimos caracteres serão lembrados.",
