  "De l'ouverture du ticket à son encaissement, sur les ventes servies à table ; recalculée sur chaque pas.": "Da abertura da conta à sua cobrança, nas vendas servidas à mesa; recalculada em cada intervalo.",
  "Couverts des réservations honorées, non pointées et prévues ; ni les annulées ni les no-show.": "Cobertos das reservas honradas, sem registo e previstas; nem as anuladas nem os no-shows.",
  "Réservations valides, annulées exclues. Une table est une réservation, pas une table de la salle.": "Reservas válidas, excluídas as anuladas. Uma mesa é uma reserva, não uma mesa da sala.",
  "Réservations marquées no-show.": "Reservas marcadas como no-show.",
  "No-show divisés par les réservations échues ; recalculé sur chaque pas.": "No-shows divididos pelas reservas vencidas; recalculado em cada intervalo.",
  "Réservations annulées divisées par toutes les réservations ; recalculé sur chaque pas.": "Reservas anuladas divididas por todas as reservas; recalculado em cada intervalo.",
  "Réservations passées restées sans arrivée ni no-show, divisées par les réservations échues.": "Reservas passadas que ficaram sem chegada nem no-show, divididas pelas reservas vencidas.",
  "Couverts divisés par la capacité des services ouverts, d'après les réglages de la réservation en ligne.": "Cobertos divididos pela capacidade dos serviços abertos, segundo as definições da reserva online.",
  "Couverts divisés par les réservations comptées ; recalculé sur chaque pas.": "Cobertos divididos pelas reservas contadas; recalculado em cada intervalo.",
  "Couverts divisés par les jours ouverts du pas ; sans réglages, par les jours qui ont une réservation.": "Cobertos divididos pelos dias abertos do intervalo; sem definições, pelos dias que têm uma reserva.",
  "Montant des factures d'achat non exclues : total hors TVA, à défaut TVA comprise, à défaut somme des lignes lues. Jour de la date de facture.": "Montante das faturas de compra não excluídas: total sem IVA, senão com IVA, senão soma das linhas lidas. Dia da data da fatura.",
  "Nombre de factures d'achat qui portent un montant ; les bons de livraison et de commande ne comptent pas.": "Número de faturas de compra com montante; as guias de remessa e as notas de encomenda não contam.",
  "Chiffre du jour saisi ou clôturé par la caisse, à défaut ventes de la caisse reliée, plus les notes de séjour d'un hôtel.": "Número do dia introduzido ou fechado pela caixa, senão vendas da caixa ligada, mais as contas de estadia de um hotel.",
  "Ventes moins la TVA, calculée sur le total de chaque taux : la somme des points peut s'écarter du total de quelques centimes.": "Vendas menos o IVA, calculado sobre o total de cada taxa: a soma dos pontos pode afastar-se do total em alguns cêntimos.",
  "Achats hors TVA de la période, par date de facture, avec la règle des Analyses des dépenses.": "Compras sem IVA do período, por data de fatura, com a regra das Análises das despesas.",
  "Coût matière divisé par le chiffre d'affaires hors TVA ; recalculé sur chaque pas.": "Custo de matéria dividido pelo volume de negócios sem IVA; recalculado em cada intervalo.",
  "Chiffre d'affaires hors TVA moins le coût matière, recalculée sur chaque pas ; n/a pour un pas sans vente ou sans facture chiffrée.": "Volume de negócios sem IVA menos o custo de matéria, recalculada em cada intervalo; n/d para um intervalo sem venda ou sem fatura com valor.",
  "Charges fixes saisies, au prorata des jours du pas.": "Custos fixos introduzidos, proporcionais aos dias do intervalo.",
  "Estimation depuis les heures pointées, les salaires saisis et les charges sociales. Réservé à la direction.": "Estimativa a partir das horas registadas, dos salários introduzidos e dos encargos sociais. Reservado à direção.",
  "Coût du personnel estimé divisé par le chiffre d'affaires hors TVA. Réservé à la direction.": "Custo do pessoal estimado dividido pelo volume de negócios sem IVA. Reservado à direção.",
