  "Jours entre la prise de la réservation et le service, en moyenne ; une saisie après coup compte zéro. Recalculé sur chaque pas.": "Dias entre o registo da reserva e o serviço, em média; uma introdução feita depois conta zero. Recalculado em cada intervalo.",
  "La moitié des réservations sont prises moins de jours avant le service, l'autre moitié plus. Recalculé sur chaque pas.": "Metade das reservas é feita menos dias antes do serviço, a outra metade mais. Recalculado em cada intervalo.",
