  "Fiches clients différentes parmi les réservations comptées ; recalculé sur chaque pas, un client présent sur deux pas compte dans chacun.": "Fichas de clientes diferentes entre as reservas contadas; recalculado em cada intervalo, um cliente presente em dois intervalos conta em cada um.",
