  "Comme l'appareil suit le réglage clair ou sombre du téléphone, de la tablette ou de l'ordinateur. Le bouton de la barre du haut bascule entre clair et sombre.": "Como o aparelho segue a definição clara ou escura do telemóvel, do tablet ou do computador. O botão da barra de cima alterna entre claro e escuro.",
  "Le texte de l'app sur cet appareil. Les exports PDF ne changent pas.": "O texto da app neste aparelho. As exportações PDF não mudam.",
  "Hauteur des lignes, des boutons et des champs, et marges de la page. Compacte se règle à la souris : au doigt, chaque cible garde 44 px.": "Altura das linhas, dos botões e dos campos, e margens da página. Compacta regula-se com o rato: com o dedo, cada alvo mantém 44 px.",
  "Le bouton principal, la pilule choisie et l'entrée choisie du menu. Pétrole est la couleur de la marque.": "O botão principal, a pílula escolhida e a entrada escolhida do menu. Petróleo é a cor da marca.",
  "Plus de fondus ni de glissements : les écrans changent d'un coup.": "Sem desvanecimentos nem deslizes: os ecrãs mudam de uma vez.",
  "Textes secondaires plus foncés, filets et contours plus marqués.": "Textos secundários mais escuros, linhas e contornos mais marcados.",
  "Original garde le texte tel qu'il a été saisi. English, Español, Deutsch, Italiano et Português traduisent l'écran, pas les données. Le sélecteur de la barre du haut fait la même chose.": "Original mantém o texto tal como foi introduzido. English, Español, Deutsch, Italiano e Português traduzem o ecrã, não os dados. O seletor da barra de cima faz o mesmo.",
