  "Automatique choisit d'après l'écran. Ordinateur : le menu sur le côté. Tablette et Téléphone : la page d'accueil en tuiles.": "Automático escolhe conforme o ecrã. Computador: o menu de lado. Tablet e Telemóvel: a página inicial em mosaicos.",
  "Les modules avec leur nom plutôt que le rail d'icônes. Le bouton à gauche du titre et Ctrl + B font la même chose.": "Os módulos com o seu nome em vez da barra de ícones. O botão à esquerda do título e Ctrl + B fazem o mesmo.",
  "Glisser depuis le bord gauche de l'écran pour revenir en arrière. Automatique : seulement dans l'app installée sur iPhone et iPad, où le système n'a pas ce geste.": "Deslizar a partir da margem esquerda do ecrã para voltar atrás. Automático: só na app instalada no iPhone e no iPad, onde o sistema não tem este gesto.",
