  "Contrôler le temps de travail": "Controlar o tempo de trabalho",
  "Le planning signale, sur l'horaire concerné, ce qui sort des règles ci-dessous. Il ne bloque rien. Seules les personnes qui écrivent le planning le voient.": "A escala assinala, no horário em causa, o que sai das regras abaixo. Não bloqueia nada. Só as pessoas que escrevem a escala o veem.",
  "Repos entre deux journées": "Descanso entre dois dias",
