  "15 minutes au-delà de 5 h 30 de travail, 30 minutes au-delà de 7 h, 1 heure au-delà de 9 h. La coupure d'un service coupé compte comme pause.": "15 minutos acima de 5 h 30 de trabalho, 30 minutos acima de 7 h, 1 hora acima de 9 h. O intervalo de um serviço partido conta como pausa.",
