  "Ces repères se calculent sur les horaires prévus de la période affichée : repos, jours de repos, jours d'affilée, pauses et durée de la journée.": "Estas referências calculam-se sobre os horários previstos do período apresentado: descanso, dias de descanso, dias seguidos, pausas e duração do dia.",
  "Cet enregistrement ne respecte pas la règle suivante. Vous pouvez revenir pour corriger l'horaire, ou enregistrer quand même.": "Este registo não respeita a regra seguinte. Pode voltar para corrigir o horário, ou guardar mesmo assim.",
  "Cet enregistrement ne respecte pas les règles suivantes. Vous pouvez revenir pour corriger l'horaire, ou enregistrer quand même.": "Este registo não respeita as regras seguintes. Pode voltar para corrigir o horário, ou guardar mesmo assim.",
  "La loi demande 11 heures, ou 8 heures une fois par semaine.": "A lei exige 11 horas, ou 8 horas uma vez por semana.",
  "C'est permis une fois par semaine, si la moyenne sur deux semaines atteint 11 heures.": "É permitido uma vez por semana, se a média em duas semanas atingir 11 horas.",
  "Un seul repos de moins de 11 heures est permis par semaine.": "Só é permitido um descanso de menos de 11 horas por semana.",
  "Septième jour d'affilée : permis si chaque journée reste sous 9 heures et si 83 heures de repos suivent.": "Sétimo dia seguido: permitido se cada dia ficar abaixo de 9 horas e se se seguirem 83 horas de descanso.",
  "Septième jour d'affilée : prévoyez ensuite 83 heures de repos d'affilée.": "Sétimo dia seguido: preveja depois 83 horas de descanso seguidas.",
  "Septième jour d'affilée avec une journée de plus de 9 heures. Six jours au plus, sept à titre d'exception.": "Sétimo dia seguido com um dia de mais de 9 horas. Seis dias no máximo, sete a título excecional.",
  "Septième jour d'affilée sans 83 heures de repos à la suite. Six jours au plus, sept à titre d'exception.": "Sétimo dia seguido sem 83 horas de descanso a seguir. Seis dias no máximo, sete a título excecional.",
  "Plus de sept jours de travail d'affilée. Six jours au plus, sept à titre d'exception.": "Mais de sete dias de trabalho seguidos. Seis dias no máximo, sete a título excecional.",
  "Aucun jour de repos entier dans la semaine. Un jour d'au moins 24 heures est obligatoire.": "Nenhum dia de descanso inteiro na semana. Um dia de pelo menos 24 horas é obrigatório.",
  "Un seul jour de repos dans la semaine. Le second est à rendre dans les 4 semaines.": "Só um dia de descanso na semana. O segundo deve ser compensado nas 4 semanas seguintes.",
  "Un seul jour de repos dans la semaine. Le second est à rendre dans les 12 semaines.": "Só um dia de descanso na semana. O segundo deve ser compensado nas 12 semanas seguintes.",
  "Pause trop courte pour la journée : 15 min au-delà de 5 h 30, 30 min au-delà de 7 h, 1 h au-delà de 9 h.": "Pausa demasiado curta para o dia: 15 min acima de 5 h 30, 30 min acima de 7 h, 1 h acima de 9 h.",
  "Un service de plus de 5 h 30 sans pause. Une pause de 15 min au moins est demandée.": "Um turno de mais de 5 h 30 sem pausa. É exigida uma pausa de pelo menos 15 min.",
  "La journée doit tenir dans 14 heures, pauses comprises.": "O dia deve caber em 14 horas, pausas incluídas.",
  "Au-delà de la moyenne de la CCNT. Les heures en plus sont à compenser ou à payer.": "Acima da média da CCNT. As horas a mais devem ser compensadas ou pagas.",
  "Clore un pointage oublié après": "Fechar um registo de ponto esquecido depois de",
  "Si le départ n'est pas pointé, l'horaire est clos à l'heure de fin prévue, une fois ce délai passé depuis l'arrivée. Le contrôle passe toutes les heures. Le planning affiche l'horaire comme clos d'office. Un départ pointé ensuite, ou une correction, remplace cette heure.": "Se a saída não for registada, o horário é fechado à hora de fim prevista, passado este prazo desde a entrada. O controlo corre de hora a hora. A escala mostra o horário como fechado automaticamente. Uma saída registada depois, ou uma correção, substitui esta hora.",
