  "effet de la météo non mesurable : il faut au moins 8 jours de pluie ou de neige et 8 jours secs comparables. La météo s'affiche sans corriger la prévision.": "efeito da meteorologia não mensurável: são precisos pelo menos 8 dias de chuva ou de neve e 8 dias secos comparáveis. A meteorologia aparece sem corrigir a previsão.",
  "effet de la météo non mesurable : vos couverts ne changent pas assez entre jours de pluie et jours secs. La météo s'affiche sans corriger la prévision.": "efeito da meteorologia não mensurável: os seus cobertos não mudam o suficiente entre dias de chuva e dias secos. A meteorologia aparece sem corrigir a previsão.",
  "effet de la météo non mesurable : aucune station de mesure MétéoSuisse à moins de 25 km. La météo s'affiche sans corriger la prévision.": "efeito da meteorologia não mensurável: nenhuma estação de medição MétéoSuisse a menos de 25 km. A meteorologia aparece sem corrigir a previsão.",
