  "Ce produit est en rupture jusqu'à demain matin. Remis en vente, il se commande de nouveau sur toutes les caisses.": "Este produto está esgotado até amanhã de manhã. De novo à venda, volta a poder ser pedido em todas as caixas.",
  "En rupture, la case est grisée sur toutes les caisses et le produit ne se commande plus. Il revient en vente tout seul demain matin.": "Esgotado, a casa fica a cinzento em todas as caixas e o produto já não pode ser pedido. Volta à venda sozinho amanhã de manhã.",
  "Ils reviennent en vente tout seuls demain matin. Vous pouvez les remettre en vente avant.": "Voltam à venda sozinhos amanhã de manhã. Pode voltar a pô-los à venda antes.",
  "Ils reviennent en vente demain matin, ou quand un responsable les remet en vente.": "Voltam à venda amanhã de manhã, ou quando um responsável os voltar a pôr à venda.",
  "En rupture jusqu'à demain matin. La case est grisée sur toutes les caisses.": "Esgotado até amanhã de manhã. A casa fica a cinzento em todas as caixas.",
